get_circuit_breaker_stats_external_api_circuit_breaker() {
    local state_dir="${FLOWSH_TEMP_DIR:-/tmp}/circuit_breaker_external_api_circuit_breaker"
    
    if [[ -d "$state_dir" ]]; then
        local current_state=$(cat "$state_dir/state" 2>/dev/null || echo "UNKNOWN")
        local failure_count=$(cat "$state_dir/failures" 2>/dev/null || echo "0")
        local success_count=$(cat "$state_dir/successes" 2>/dev/null || echo "0")
        
        cat << EOF
=== Circuit Breaker Stats (external_api_circuit_breaker) ===
State: $current_state
Failures: $failure_count/${failure_threshold}
Successes: $success_count/${success_threshold}
Timeout: 90s
Monitor Window: 240s
=====================================
EOF
    else
        echo "Circuit breaker not initialized"
    fi
}

